function CatHouseExploreTaskTeamListPanel:SetPanelInfo(taskData, exploreId)
    local requireServices = checkTable(CatHouseExploreMgr:GetExploreRequireData(exploreId))
    local requireData = CatHouseExploreMgr:GetRequireDataByIndex(requireServices, checkNumber(taskData.taskId))
    self.requireData = requireData
    print("->self.requireData", table.dump(checkTable(requireServices)), 
            table.dump(checkTable(CatHouseExploreMgr:GetTaskExtraCondition(checkNumber(taskData.taskId)))), 
            table.dump(checkTable(requireData)))
    local nunPreCatCost = taskData.strengthNum
    if not IsNull(self.TxtNum) then
        self.TxtNum.text = checkString(nunPreCatCost)
    end
    self.attributeId = taskData.attributeId
    self.TextAttribute.text = CatHouseExploreMgr:GetCatHouseTaskData(taskData.taskId).attributeDesc
    local attributeData = CfUtils.GetCfVo(AutoIds.IdSetting1901, "CatHouseCatAttributeVo", checkNumber(self.attributeId))
    local pathIcon = checkString(attributeData.picture)
    self.ImgIcon:LoadSprite(pathIcon)
    self:RefreshCatTeamList()
end

function CatHouseExploreTaskTeamListPanel:RefreshCatTeamList()
    local catsNum = CatHouseExploreMgr.EXPLORE_TEAM_CAT_MAX
    if self.List.IsListViewInit then
        GameUtils.ReloadData(self.List, catsNum)
    else
        self.List:InitGridView(catsNum, Bind(self, self.OnGetItemByIndex))
    end
end

function CatHouseExploreTaskTeamListPanel:SetTeamAttributeValue(value)
    if not isNull(self.TextNumber) then
        self.TextNumber.text = value
    end 
end

function CatHouseExploreTaskTeamListPanel:OnGetItemByIndex(gridView, index, row, column)
    if index < 0 then return end
    local indexInCatsList = index + 1
    local catData = CatHouseExploreMgr.listCatsTeam[indexInCatsList]
    local prefabPath = PREFAB_CAT_CELL
    local cell = gridView:NewListViewItem(prefabPath)
    if not IsNull(cell) then
        local cellLB = GetLuaBehaviour(cell.gameObject, PATH_LUA_CELL)
        if cellLB then
            if isNull(cellLB.Env) then cellLB:Init() end
            local cellLT = cellLB.Env
            cellLT:InitCell(catData, self.attributeId, self.requireData)
            KTool.SetActive(cellLT.controller.gameObject, true)
        end
    end
    return cell
end


